const originalTopics = {
  spring: ['forces', 'parameters', 'motion', 'parameters'], pendulum: ['parameters', 'parameters', 'motion', 'motion'],
  'double-spring': ['forces', 'forces', 'parameters', 'parameters'], basketball: ['motion', 'forces', 'motion', 'parameters'],
  pulley: ['forces', 'forces', 'motion', 'parameters'], incline: ['forces', 'forces', 'parameters', 'forces'],
  elevator: ['forces', 'forces', 'forces', 'parameters'], 'friction-stacked': ['forces', 'forces', 'motion', 'forces'],
  'friction-table': ['forces', 'motion', 'forces', 'parameters'], 'friction-hanging': ['forces', 'forces', 'motion', 'forces'],
  carousel: ['forces', 'motion', 'parameters', 'parameters'], 'rotating-tube': ['forces', 'forces', 'parameters', 'parameters'],
  'two-string': ['forces', 'forces', 'forces', 'forces'], 'energy-bowl': ['energy', 'motion', 'forces', 'forces'],
};
export function assembleQuestions(system, existing) {
  const added = intuitionQuestions[system];
  if (!added) throw new Error(`Missing intuition bank: ${system}`);
  return [...existing, ...added].map((item, index) => {
    const result = { ...item, id: `${system}-${index + 1}`, topic: item.topic ?? originalTopics[system][index], difficulty: index < 4 ? 'foundation' : index < 8 ? 'reasoning' : 'challenge' };
    if (index < existing.length) return result;
    const offset = index % item.options.en.length;
    const rotate = values => values.slice(offset).concat(values.slice(0, offset));
    result.options = { en: rotate(item.options.en), he: rotate(item.options.he) };
    result.feedback = { en: rotate(item.feedback.en), he: rotate(item.feedback.he) };
    result.correct = (item.correct - offset + item.options.en.length) % item.options.en.length;
    return result;
  });
}
